package com.aicharacter.v3;import org.json.JSONObject;
public final class WorldHistoryEntry {public long time;public String eventId,type,entity,summary;public WorldHistoryEntry(long t,String ty,String e,String s){this(t,"legacy_"+Long.toHexString(t)+"_"+Integer.toHexString((ty+e+s).hashCode()),ty,e,s);}public WorldHistoryEntry(long t,String id,String ty,String e,String s){time=t;eventId=id;type=ty;entity=e;summary=s;}public JSONObject toJson(){JSONObject j=new JSONObject();try{j.put("time",time);j.put("eventId",eventId);j.put("type",type);j.put("entity",entity);j.put("summary",summary);}catch(Exception ignored){}return j;}public static WorldHistoryEntry fromJson(JSONObject j){long t=j.optLong("time");String ty=j.optString("type"),e=j.optString("entity"),s=j.optString("summary");return new WorldHistoryEntry(t,j.optString("eventId","legacy_"+Long.toHexString(t)+"_"+Integer.toHexString((ty+e+s).hashCode())),ty,e,s);}}
